exercise.solution:
def petit_calcul(raw):
    import ast
    if len(raw)>100:raise ValueError('trop long')
    def visiter(n):
        if isinstance(n,ast.Constant) and type(n.value) in (int,float):return n.value
        if isinstance(n,ast.BinOp) and type(n.op) in (ast.Add,ast.Sub,ast.Mult):
            a,b=visiter(n.left),visiter(n.right)
            return a+b if isinstance(n.op,ast.Add) else a-b if isinstance(n.op,ast.Sub) else a*b
        raise ValueError('noeud interdit')
    return visiter(ast.parse(raw,mode='eval').body)

exercise.check:
assert petit_calcul('2+3*4')==14
assert petit_calcul('7-9')==-2
for raw in ['abs(2)','True+1','2**3']:
    try:petit_calcul(raw)
    except ValueError:pass
    else:raise AssertionError('noeud interdit accepté')

