def place_restante(budget, systeme, demande, reserve):
    if min(budget,systeme,demande,reserve)<0:raise ValueError('budget négatif')
    reste=budget-systeme-demande-reserve
    if reste<0:raise ValueError('contexte insuffisant')
    return reste

