def appels_incertains(evenements):
    ouverts={}
    for e in evenements:
        if e['kind']=='tool_started':ouverts[e['call_id']]=True
        elif e['kind']=='tool_finished':ouverts.pop(e['call_id'],None)
    return list(ouverts)

def taux_reussite(lignes):
    n=len(lignes);k=sum(r.get('ok') is True for r in lignes)
    return {'total':n,'succes':k,'taux':k/n if n else None}

