def ecarts_graines(base, variante):
    a={r['seed']:r['score'] for r in base};b={r['seed']:r['score'] for r in variante}
    if set(a)!=set(b) or not a:raise ValueError('graines non appariées')
    return [b[k]-a[k] for k in sorted(a)]

